#!/bin/sh
# Installs 261012lntx26f. Generated by ToDesktop.
set -eu

BASE='https://v2-edge-dev.todesktop.workers.dev'
APP='261012lntx26f'
COHORT=''
METHOD='auto'

for arg in "$@"; do
  case "$arg" in
    --tarball) METHOD=tarball ;;
    --cohort=*) COHORT="${arg#--cohort=}" ;;
  esac
done
case "$COHORT" in
  *[!A-Za-z0-9_-]*) echo "Invalid cohort: $COHORT" >&2; exit 1 ;;
esac

INSTALL_ID=$(cat /proc/sys/kernel/random/uuid 2>/dev/null || od -An -N16 -tx1 /dev/urandom | tr -d ' \n')
REPO="$BASE/$APP/r/$INSTALL_ID/${COHORT:-_}"

as_root() {
  if [ "$(id -u)" = 0 ]; then "$@"
  elif command -v sudo >/dev/null 2>&1; then sudo "$@"
  else echo "Root is needed for a system install. Rerun with: sh -s -- --tarball" >&2; exit 1
  fi
}

pick_method() {
  if [ "$METHOD" != auto ]; then echo "$METHOD"
  elif command -v apt-get >/dev/null 2>&1; then echo apt
  elif command -v dnf >/dev/null 2>&1; then echo dnf
  elif command -v pacman >/dev/null 2>&1; then echo pacman
  else echo tarball
  fi
}

install_apt() {
  as_root mkdir -p /etc/apt/keyrings
  curl -fsSL "$BASE/$APP/key.gpg" | as_root tee "/etc/apt/keyrings/$APP.gpg" >/dev/null
  printf 'Types: deb\nURIs: %s/apt\nSuites: stable\nComponents: main\nArchitectures: amd64\nSigned-By: /etc/apt/keyrings/%s.gpg\n' \
    "$REPO" "$APP" | as_root tee "/etc/apt/sources.list.d/$APP.sources" >/dev/null
  as_root apt-get update -o "Dir::Etc::sourcelist=sources.list.d/$APP.sources" -o Dir::Etc::sourceparts=- -o APT::Get::List-Cleanup=0
  as_root apt-get install -y "$APP"
}

install_dnf() {
  printf '[%s]\nname=%s\nbaseurl=%s/rpm\nenabled=1\ngpgcheck=1\nrepo_gpgcheck=1\ngpgkey=%s/%s/key.asc\n' \
    "$APP" "$APP" "$REPO" "$BASE" "$APP" | as_root tee "/etc/yum.repos.d/$APP.repo" >/dev/null
  as_root dnf install -y "$APP"
}

install_pacman() {
  key=$(mktemp)
  curl -fsSL "$BASE/$APP/key.asc" -o "$key"
  fingerprint=$(gpg --with-colons --show-keys "$key" | awk -F: '/^fpr/ { print $10; exit }')
  as_root pacman-key --add "$key"
  as_root pacman-key --lsign-key "$fingerprint"
  rm -f "$key"
  if ! grep -q "^\[$APP\]" /etc/pacman.conf; then
    printf '\n[%s]\nSigLevel = PackageOptional DatabaseRequired\nServer = %s/pacman/$arch\n' \
      "$APP" "$REPO" | as_root tee -a /etc/pacman.conf >/dev/null
  fi
  as_root pacman -Sy --noconfirm "$APP"
}

# Runs the app as a systemd service, so it starts at login (for root, at
# boot) and comes back after the updater restarts it: a user service, or
# for root a system one. Optional: it returns 1 when there's no systemd to
# ask, or it says why it couldn't, and the caller says how to run the app.
start_service() {
  if [ "$(id -u)" = 0 ]; then scope=system; wanted_by=multi-user.target
  else scope=user; wanted_by=default.target
  fi
  systemctl --$scope show-environment >/dev/null 2>&1 || return 1
  # The unit goes where this systemd reads units from. A HOME or
  # XDG_CONFIG_HOME changed for this script, or another user's bus, isn't.
  paths=" $(systemctl --$scope show --property=UnitPath 2>/dev/null | sed 's/^UnitPath=//') "
  units=
  for dir in "${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user" "$HOME/.config/systemd/user" /etc/systemd/system; do
    case "$paths" in *" $dir "*) units=$dir; break ;; esac
  done
  if [ -z "$units" ]; then
    echo "Not starting $APP as a $scope service: systemd doesn't read units from ${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user."
    return 1
  fi
  # Restart, not start: a re-run that replaced the files restarts the
  # service on them.
  if mkdir -p "$units" &&
    printf '[Unit]\nDescription=%s\n\n[Service]\nExecStart="%s/current/%s"\nRestart=always\nRestartSec=1\n\n[Install]\nWantedBy=%s\n' \
      "$APP" "$root" "$executable" "$wanted_by" > "$units/$APP.service" &&
    systemctl --$scope daemon-reload &&
    systemctl --$scope enable "$APP.service" &&
    systemctl --$scope restart "$APP.service"; then
    echo "Installed $APP and started it as a $scope service."
    if [ $scope = user ] && loginctl show-user "$(id -un)" --property=Linger 2>/dev/null | grep -qx Linger=no; then
      echo "It runs while you're logged in. To keep it running after you log out: loginctl enable-linger"
    fi
    return 0
  fi
  echo "Couldn't start $APP as a $scope service (see above; $units/$APP.service)."
  return 1
}

install_tarball() {
  root="${XDG_DATA_HOME:-$HOME/.local/share}/$APP"
  bin="$HOME/.local/bin"
  tmp=$(mktemp -d)
  trap 'rm -rf "$tmp"' EXIT
  link="$BASE/$APP/download/linux/tar.gz"
  [ -n "$COHORT" ] && link="$BASE/$APP/c/$COHORT/download/linux/tar.gz"
  curl -fsSL "$link" -o "$tmp/app.tar.gz"
  mkdir "$tmp/app"
  tar -xzf "$tmp/app.tar.gz" -C "$tmp/app"
  identity="$tmp/app/todesktop-build.json"
  build_id=$(sed -n 's/.*"buildId": *"\([^"]*\)".*/\1/p' "$identity")
  executable=$(sed -n 's/.*"executable": *"\([^"]*\)".*/\1/p' "$identity")
  if [ -z "$build_id" ] || [ -z "$executable" ]; then
    echo "The download has no build ID or executable in todesktop-build.json." >&2
    exit 1
  fi

  # Reinstalling keeps the install's ID, and with it its rollout buckets.
  if [ -f "$root/install.json" ]; then
    kept=$(sed -n 's/.*"installId": *"\([A-Za-z0-9_-]*\)".*/\1/p' "$root/install.json")
    if [ -n "$kept" ]; then INSTALL_ID=$kept; fi
  fi

  # Unpacked next to the versions, then swapped in, as the updater does: a
  # running service keeps its files until it's restarted.
  mkdir -p "$root/versions" "$bin"
  staging="$root/versions/.$build_id.partial"
  rm -rf "$staging"
  mv "$tmp/app" "$staging"
  rm -rf "$root/versions/$build_id"
  mv "$staging" "$root/versions/$build_id"
  ln -sfn "versions/$build_id" "$root/current"
  cohort_json=null
  [ -n "$COHORT" ] && cohort_json="\"$COHORT\""
  printf '{"installId":"%s","cohort":%s}\n' "$INSTALL_ID" "$cohort_json" > "$root/install.json"
  ln -sf "$root/current/$executable" "$bin/$executable"

  if ! start_service; then
    echo "Installed $APP to $root. Run it with: $bin/$executable"
  fi
}

case "$(pick_method)" in
  apt) install_apt ;;
  dnf) install_dnf ;;
  pacman) install_pacman ;;
  *) install_tarball ;;
esac
